// What implements Host. Ones left out give zero, or Unsupported for a result
#[allow(clippy::all, unused_unsafe)]
pub trait HostImpl {
    fn keep(&self, size: usize, alignment: usize) -> *mut ::core::ffi::c_void {
        let _ = (size, alignment,);
        unsafe { ::core::mem::zeroed() }
    }
    fn owner(&self, name: &str) -> *mut Owner {
        let _ = (name,);
        unsafe { ::core::mem::zeroed() }
    }
    fn adopt(&self, obj: crate::Object, owner: *mut Owner) -> crate::Object {
        let _ = (obj, owner,);
        unsafe { ::core::mem::zeroed() }
    }
    fn adapt(&self, obj: crate::Object, want: *mut Info) -> crate::Object {
        let _ = (obj, want,);
        unsafe { ::core::mem::zeroed() }
    }
    fn promise(&self, size: usize, resolver: *mut Resolver) -> Promise {
        let _ = (size, resolver,);
        unsafe { ::core::mem::zeroed() }
    }
    fn provide(&self, name: &str, major: u32, obj: crate::Object) -> u32 {
        let _ = (name, major, obj,);
        unsafe { ::core::mem::zeroed() }
    }
    fn withdraw(&self, name: &str, major: u32) {
        let _ = (name, major,);
        ()
    }
    fn get(&self, name: &str, major: u32, want: *mut Info) -> crate::Object {
        let _ = (name, major, want,);
        unsafe { ::core::mem::zeroed() }
    }
    fn wait(&self, name: &str, major: u32, want: *mut Info, resolver: Resolver) -> bool {
        let _ = (name, major, want, resolver,);
        unsafe { ::core::mem::zeroed() }
    }
    fn queue(&self) -> Queue {
        unsafe { ::core::mem::zeroed() }
    }
    fn release(&self, obj: crate::Object) {
        let _ = (obj,);
        ()
    }
    fn releasable(&self, owner: *mut Owner, hook: Release) -> bool {
        let _ = (owner, hook,);
        unsafe { ::core::mem::zeroed() }
    }
    fn explain(&self, name: &str, message: &str) {
        let _ = (name, message,);
        ()
    }
    fn blob(&self, size: usize) -> Blob {
        let _ = (size,);
        unsafe { ::core::mem::zeroed() }
    }
    fn explanation(&self, name: &str) -> &str {
        let _ = (name,);
        ""
    }
    fn to_json(&self, value: crate::Any) -> Result<Blob, JsonError> {
        let _ = (value,);
        Err(<JsonError as crate::ErrorCode>::UNSUPPORTED)
    }
    fn from_json(&self, text: &str, r#type: *mut TypeInfo) -> Result<Blob, JsonError> {
        let _ = (text, r#type,);
        Err(<JsonError as crate::ErrorCode>::UNSUPPORTED)
    }
}

